/**
 * Moving a memory folder around (spec §9.1 U4, U6). The dream works on a copy; the repo's
 * `.claude/memory` changes only when the owner accepts, and then it is made equal to the copy.
 *
 * Three kinds of file, three behaviours:
 *   - `index.md` and `usage.json`: generated by the script, mirrored
 *   - `memories/*.md`: mirrored, deletions included
 *   - `README.md` and `_template.md`: the owner's, copied into the dream for the agents to read and
 *     for C20 to compare, and never mirrored back
 */
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";

import { readMemoryFiles } from "./memoryFiles.mjs";
import { renderIndex } from "./memoryIndex.mjs";
import { readUsage, syncFiles, writeUsage } from "./usage.mjs";

const GENERATED = ["index.md", "usage.json"];

/** `memories/<name>` -> contents, for the files of `dir/memories/`; empty when the folder is absent. */
const _memories = (dir) => {
  const folder = path.join(dir, "memories");
  if (!existsSync(folder)) return new Map();
  return new Map(readdirSync(folder).sort().map((name) => [`memories/${name}`, readFileSync(path.join(folder, name), "utf8")]));
};

/** A copy of the whole folder at `to`, with a `memories/` folder even when the source had none. */
export const copyMemory = (from, to) => {
  mkdirSync(to, { recursive: true });
  cpSync(from, to, { recursive: true });
  mkdirSync(path.join(to, "memories"), { recursive: true });
};

/**
 * What the memories of `to` have that `from` does not (`created`), what differs (`modified`) and
 * what `from` has that `to` lacks (`deleted`). Paths are `memories/<name>`, sorted.
 */
export const compareMemories = (from, to) => {
  const before = _memories(from);
  const after = _memories(to);
  return {
    created: [...after.keys()].filter((name) => !before.has(name)),
    modified: [...after.keys()].filter((name) => before.has(name) && before.get(name) !== after.get(name)),
    deleted: [...before.keys()].filter((name) => !after.has(name)),
  };
};

/**
 * Makes `to`'s generated files and `memories/` equal to `from`'s, a file `from` no longer has
 * deleted. `README.md` and `_template.md` are not touched.
 */
export const mirrorMemory = (from, to) => {
  mkdirSync(path.join(to, "memories"), { recursive: true });
  for (const name of GENERATED) writeFileSync(path.join(to, name), readFileSync(path.join(from, name)));
  const wanted = _memories(from);
  for (const name of _memories(to).keys()) {
    if (!wanted.has(name)) rmSync(path.join(to, name), { force: true });
  }
  for (const [name, contents] of wanted) writeFileSync(path.join(to, name), contents);
};

/** Every file of the folder, `index.md` and the owner's two included, as path -> contents. */
export const snapshotMemory = (dir) =>
  new Map([
    ...[...GENERATED, "README.md", "_template.md"]
      .filter((name) => existsSync(path.join(dir, name)))
      .map((name) => [name, readFileSync(path.join(dir, name), "utf8")]),
    ..._memories(dir),
  ]);

/** The paths whose contents differ between two snapshots, one that exists in only one included. Sorted. */
export const changedPaths = (before, after) =>
  [...new Set([...before.keys(), ...after.keys()])].filter((name) => before.get(name) !== after.get(name)).sort();

/**
 * Brings `usage.json` and `index.md` of a folder in line with its `memories/`: an entry for each
 * file (a new one created today), none for a file that is gone, then the index rendered from the
 * files' titles and summaries. `change` may adjust the usage first (the reads counted); it gets the
 * synced usage and returns the one to keep. A file with no title or summary is left out of the
 * index: C20 reports it. Returns the memory files read.
 */
export const refreshIndex = (dir, now, change = (usage) => usage) => {
  const { files } = readMemoryFiles(dir);
  const usage = change(syncFiles(readUsage(dir), files.map((file) => file.path), now.toISOString().slice(0, 10)));
  writeUsage(dir, usage);
  const listed = files.filter((file) => file.title !== null && file.summary !== null);
  writeFileSync(path.join(dir, "index.md"), renderIndex({ files: listed, usage, now }));
  return files;
};
